LAYER
  NAME "gebco_latest_shaded_relief"
  TYPE RASTER
  STATUS ON
  CONNECTIONTYPE WMS
  CONNECTION "https://wms.gebco.net/mapserv?"

  PROJECTION
    "init=epsg:4326"
  END

  METADATA
    "wms_title" "GEBCO Global Bathymetry and Topography - Shaded Relief (Latest)"
    "wms_abstract" "This map shows the shape of the ocean floor and land surface using global bathymetry and topography data from the General Bathymetric Chart of the Oceans (GEBCO). Shaded relief highlights underwater features such as mid-ocean ridges, seamounts, deep-sea trenches and continental slopes. It helps users explore the physical structure of the ocean, understand the diversity of seafloor landscapes and identify features that influence marine environments. The map combines measured and estimated depth information and is intended for visual exploration rather than navigation."
    "wms_name" "GEBCO_LATEST"
    "wms_server_version" "1.3.0"
    "wms_format" "image/png"
    "wms_srs" "EPSG:4326"
    "wms_extent" "-180 -90 180 90"
    "wms_connectiontimeout" "60"
    "wms_attribution_text" "General Bathymetric Chart of the Oceans (GEBCO)"
    "wms_attribution_onlineresource" "https://www.gebco.net/"
    "wms_metadataurl_href" "https://www.gebco.net/data-products/gebco-web-services/web-map-service"
    "wms_metadataurl_format" "text/html"
    "wms_metadataurl_type" "TC211"
  END
END
